import {uid,escapeHTML as e,initialProject,parseCSV,analyzeCSV,validateProject,schematicSVG} from './core.js';
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',circuit:'M2 12h4m12 0h4 M6 6h12v12H6z M9 2v4m6-4v4M9 18v4m6-4v4',flask:'M9 3h6m-5 0v7L4 20h16l-6-10V3 M7 15h10',layers:'m12 3 10 5-10 5L2 8z M2 12l10 5 10-5M2 16l10 5 10-5',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',spark:'m12 3 2.7 6.3L21 12l-6.3 2.7L12 21l-2.7-6.3L3 12l6.3-2.7z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',down:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',upload:'M12 16V3m-5 5 5-5 5 5M4 17v4h16v-4',chevron:'m9 5 7 7-7 7',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',file:'M14 2H5v20h14V7z M14 2v6h5M8 12h8m-8 4h6',bolt:'m13 2-9 12h7l-1 8 10-13h-7z',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14m5 12 6 6',edit:'m15 4 5 5M4 16 16 4a3 3 0 0 1 4 4L8 20H4z'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.file}"/></svg>`;
const KEY='circuit-journal-workspace-v2';let state,storageBroken=false;
try{const stored=localStorage.getItem(KEY);state=stored?JSON.parse(stored):{projects:[],active:null};if(!Array.isArray(state.projects))throw Error();state.projects.forEach(validateProject);}catch{storageBroken=true;state={projects:[],active:null};}
state.active=state.projects.some(p=>p.id===state.active)?state.active:state.projects[0]?.id||null;
let lastRenderedPage=null,connectionProof=null,connectionTesting=false,connectionError='';
let page='overview',connection={connected:false,model:'gpt-6-luna',provider:'Portkey'},busy=false,modalReturn=null;
const p=()=>state.projects.find(x=>x.id===state.active);
const date=s=>new Date(s).toLocaleString('en-US',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
const fmt=n=>Number.isFinite(n)?Number(n.toPrecision(5)).toString():'—';
const button=(action,label,cls='',extra='')=>`<button type="button" data-action="${action}" class="${cls}" ${extra}>${label}</button>`;
const badge=(text,type='')=>`<span class="badge ${type}">${e(text)}</span>`;
const status=a=>a?.status==='pass'?badge('Within limits','pass'):a?.status==='fail'?badge('Outside limits','fail'):badge('Insufficient evidence','warn');
const field=(label,name,value='',placeholder='',type='text',required=false)=>`<label class="field">${label}<input name="${name}" type="${type}" value="${e(value)}" placeholder="${e(placeholder)}" ${required?'required':''} ${type==='number'?'step="any"':''}></label>`;
const area=(label,name,value='',placeholder='')=>`<label class="field">${label}<textarea name="${name}" placeholder="${e(placeholder)}">${e(value)}</textarea></label>`;
const select=(label,name,options,value)=>`<label class="field">${label}<select name="${name}">${options.map(o=>`<option value="${e(o[0])}" ${o[0]===value?'selected':''}>${e(o[1])}</option>`).join('')}</select></label>`;
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3500);}
function save(){if(storageBroken)throw Error('The existing browser archive could not be read. Export the original archive in Settings before making changes.');try{localStorage.setItem(KEY,JSON.stringify(state));}catch{throw Error('Browser storage is full or unavailable. Export a backup and reduce the data size.');}}
function mutate(fn){const previous=JSON.stringify(state);try{fn();save();}catch(err){state=JSON.parse(previous);throw err;}}
function event(title,detail,type='note'){p().events.unshift({id:uid(),title,detail,type,date:new Date().toISOString()});}
function download(name,content,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function empty(title,desc,action,label){return `<div class="empty"><div class="empty-icon">${icon('flask')}</div><h3>${title}</h3><p>${desc}</p>${action?button(action,label,'small'):''}</div>`;}
function flow(){return `<div class="circuit-canvas"><div class="circuit-flow">${p().stages.length?p().stages.map((s,i)=>`${i?'<div class="wire"></div>':''}<button class="stage" data-action="edit-stage" data-id="${e(s.id)}"><div class="symbol">${{INPUT:'⎓',BOOST:'↗',BUCK:'↘',SWITCH:'⌁'}[s.kind]||'◇'}</div><div class="kind">${e(s.kind)}</div><strong>${e(s.name)}</strong><div class="voltage">${e(s.voltage||'?')} <small>V</small></div><div class="part">${e(s.part||'Part number pending')}</div></button>`).join(''):'<div class="diagram-empty">Start by adding a circuit module.</div>'}</div></div>`;}
function recentEvents(count=3){return p().events.slice(0,count).map(x=>`<div class="event"><strong>${e(x.title)}</strong><p>${e(x.detail)}</p><time>${date(x.date)}</time></div>`).join('');}
function overview(){const project=p();const real=project.tests.filter(t=>!t.demo);return `<div class="page-head"><div><div class="eyebrow">YOUR ENGINEERING WORKSPACE</div><h1>${e(project.name)}</h1><p class="subhead">From the first idea to every evidence-backed iteration.</p></div><div class="row">${badge(project.version)}${button('draft-requirements',icon('spark')+' Draft requirements')}${button('import-test',icon('plus')+' Log test','primary')}</div></div><div class="overview-grid"><div><div class="card hero"><div class="eyebrow">BUILD. MEASURE. UNDERSTAND.</div><h2>Every experiment moves your design forward.</h2><p>${e(project.description)}</p><div class="hero-meta"><span>PROJECT / ${e(project.category||'Hardware R&D')}</span><span>REVISION / ${e(project.version)}</span></div></div><div class="stats">${[['Circuit blocks',project.stages.length,'System-level blocks','circuit'],['Components',project.bom.length,'Parts in your bill of materials','layers'],['Test records',real.length,'Your recorded measurements','flask'],['Design decisions',project.decisions.length,'The reasoning behind each choice','file']].map(([label,value,desc,ic])=>`<div class="card stat"><div class="label">${label}${icon(ic)}</div><div class="value">${String(value).padStart(2,'0')}</div><div class="desc">${desc}</div></div>`).join('')}</div><div class="card"><div class="card-header"><h2>System architecture <span class="version-label">/ ${e(project.version)}</span></h2>${button('nav-design','Design workbench '+icon('arrow'),'small ghost')}</div>${flow()}<div class="card-foot"><span>● Architecture draft · Select a block to edit</span><span>Pin-level schematic pending</span></div></div><div class="card section-gap"><div class="card-header"><h2>Recent experiments</h2>${button('nav-tests','View all '+icon('arrow'),'small ghost')}</div>${project.tests.length?`<div class="table-wrap"><table><thead><tr><th>Test name</th><th>Design revision</th><th>Result</th><th></th></tr></thead><tbody>${project.tests.slice(0,3).map(t=>`<tr><td><strong>${e(t.title)}</strong>${t.demo?' '+badge('Sample data','warn'):''}<br><small>${date(t.date)}</small></td><td class="mono">${e(t.version)}</td><td>${status(t.analysis)}</td><td>${button('view-test','View','small',`data-id="${e(t.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('Ready for your first experiment','Import a CSV or write a lab note to connect measurements to your design.','import-test','Import test data')}</div></div><div class="stack overview-side"><div class="card insight"><h3>${icon('spark')} Let evidence guide the next step</h3><p>Start with the missing design conditions, then bring in your measurements.</p>${[['Define parts and load','Add part numbers, load, current and control logic levels.'],['Import your first test','Bring in CSV measurements or write an experiment note.'],['Compare your iterations','Connect each dataset to a revision and preserve the reasoning.']].map(([a,b],i)=>`<div class="insight-item"><span class="step-number">0${i+1}</span><div><strong>${a}</strong><p>${b}</p></div></div>`).join('')}<div style="margin-top:16px">${button('nav-assistant','Analyze with AI '+icon('arrow'),'small')}</div></div><div class="card"><div class="card-header"><h2>Project readiness</h2>${icon('check')}</div><div class="checklist">${[[true,'Project goal recorded'],[project.stages.some(s=>s.part&&s.part!=='TBD'),'Specify the part numbers'],[project.bom.length>0,'Build the bill of materials'],[real.length>0,'Import real measurements']].map(([done,label])=>`<div class="task-line"><span class="check ${done?'done':''}">${done?'✓':''}</span>${label}</div>`).join('')}</div></div><div class="card"><div class="card-header"><h2>Recent activity</h2>${button('nav-timeline',icon('arrow'),'icon small','aria-label="View project timeline"')}</div><div class="timeline-mini">${recentEvents()}</div></div></div></div><div class="tagline">GOOD HARDWARE HAS A STORY. KEEP YOURS.</div>`;}
function design(){return `<div class="page-head"><div><div class="eyebrow">DESIGN WORKBENCH</div><h1>Give every design a clear foundation</h1><p class="subhead">Keep requirements, blocks and decisions together in one revision.</p></div><div class="tab-actions">${button('new-revision',icon('layers')+' Save snapshot')}${aiButton('architecture','Draft blocks')}${button('add-stage',icon('plus')+' Add block','primary')}</div></div><div class="card"><div class="card-header"><h2>Architecture draft</h2>${button('export-svg',icon('down')+' Export SVG','small')}</div>${flow()}<div class="card-foot"><span>Editable system block diagram. Pin-level connections and component selection must be confirmed before electrical verification.</span></div></div><div class="grid-2 section-gap"><div class="card"><div class="card-header"><h2>Requirements</h2><div class="row">${button('draft-requirements',icon('spark')+' Draft with AI','small primary')}${p().requirementDraft?button('review-requirements','Review draft','small'):''}${button('add-requirement',icon('plus'),'icon small','aria-label="Add requirement"')}</div></div><div class="table-wrap"><table><tbody>${p().requirements.length?'':'<tr><td colspan="4">Describe your idea with Draft with AI, or add a requirement manually.</td></tr>'}${p().requirements.map(r=>`<tr><td>${e(r.name)}</td><td>${e(r.value)}</td><td>${r.status==='confirmed'?badge('Confirmed','pass'):badge('Pending','warn')}</td><td>${button('edit-requirement',icon('edit'),'icon small',`data-id="${e(r.id)}" aria-label="Edit requirement"`)}</td></tr>`).join('')}</tbody></table></div></div><div class="card"><div class="card-header"><h2>Design decisions</h2>${aiButton('decision','Draft decision')}${button('add-decision',icon('plus')+' Record','small')}</div>${p().decisions.length?p().decisions.map(d=>`<div class="decision"><h3>${e(d.title)}</h3><p>${e(d.detail)}</p><small>${date(d.date)}</small></div>`).join(''):empty('Keep the reasoning','Capture component choices, tradeoffs and the reason for each change.','add-decision','Record a decision')}</div></div><div class="card section-gap"><div class="card-header"><h2>Revision snapshots</h2><small>Snapshots preserve requirements, blocks and the BOM.</small></div>${p().revisions.length?`<div class="table-wrap"><table><thead><tr><th>Revision</th><th>Saved at</th><th>Notes</th><th></th></tr></thead><tbody>${p().revisions.map(r=>`<tr><td class="mono">${e(r.version)}</td><td>${date(r.date)}</td><td>${e(r.note||'')}</td><td>${button('view-revision','View snapshot','small',`data-id="${e(r.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('No snapshots yet','Save a snapshot before the next change. Tests keep their original design context.')}</div>`;}
function bom(){return `<div class="page-head"><div><div class="eyebrow">BILL OF MATERIALS</div><h1>Parts with a reason to be here</h1><p class="subhead">Keep part numbers, purpose and source material together.</p></div><div class="tab-actions">${aiButton('bom','Draft BOM')}${button('export-bom',icon('down')+' Export CSV')}${button('add-part',icon('plus')+' Add part','primary')}</div></div><div class="info-banner">Ask the assistant to research candidates, verify the manufacturer documentation, then add your selections. Unspecified parts stay unspecified.</div><div class="card">${p().bom.length?`<div class="table-wrap"><table><thead><tr><th>Reference</th><th>Part number</th><th>Purpose / parameters</th><th>Quantity</th><th>Source</th><th></th></tr></thead><tbody>${p().bom.map(r=>`<tr><td class="mono">${e(r.ref)}</td><td><strong>${e(r.part)}</strong></td><td>${e(r.value)}</td><td>${e(r.qty)}</td><td>${safeLink(r.source,'View source')}</td><td>${button('edit-part','Edit','small',`data-id="${e(r.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('Start your bill of materials','Add the components used in your design, with their specifications and sources.','add-part','Add your first part')}</div>`;}
function safeLink(url,label){try{const u=new URL(url);if(!['http:','https:'].includes(u.protocol))return '<small>No source link</small>';return `<a href="${e(u.href)}" target="_blank" rel="noopener noreferrer" class="source-link">${e(label||u.hostname)} ↗</a>`;}catch{return '<small>No source link</small>';}}
function chart(a){if(!a)return '';const w=760,h=220,left=55,right=20,top=20,bottom=36;let lo=a.min,hi=a.max;if(a.target!==null&&a.tolerance!==null){lo=Math.min(lo,a.target-a.tolerance);hi=Math.max(hi,a.target+a.tolerance);}const range=hi-lo||Math.max(Math.abs(hi)*.01,.01);lo-=range*.14;hi+=range*.14;const px=x=>left+(x-a.points[0].x)/(a.points.at(-1).x-a.points[0].x)*(w-left-right),py=y=>top+(hi-y)/(hi-lo)*(h-top-bottom);const stride=Math.max(1,Math.ceil(a.points.length/1200));let pts=a.points.filter((_,i)=>i%stride===0);if(pts.at(-1)!==a.points.at(-1))pts.push(a.points.at(-1));return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Measurement versus time"><rect width="760" height="220" fill="#fff"/>${[0,1,2,3].map(i=>{const y=lo+(hi-lo)*i/3;return `<line x1="${left}" x2="${w-right}" y1="${py(y)}" y2="${py(y)}" stroke="#edf0e8"/><text x="${left-10}" y="${py(y)+4}" text-anchor="end" font-size="10" fill="#95a18a" font-family="monospace">${fmt(y)}</text>`;}).join('')}${a.target!==null&&a.tolerance!==null?`<rect x="${left}" y="${py(a.target+a.tolerance)}" width="${w-left-right}" height="${py(a.target-a.tolerance)-py(a.target+a.tolerance)}" fill="#dcecc7" opacity=".45"/><line x1="${left}" x2="${w-right}" y1="${py(a.target)}" y2="${py(a.target)}" stroke="#8da66e" stroke-dasharray="4 4"/>`:''}<polyline points="${pts.map(q=>`${px(q.x)},${py(q.y)}`).join(' ')}" fill="none" stroke="#3f7e5a" stroke-width="1.6"/><text x="${left}" y="${h-10}" font-size="10" fill="#93a083" font-family="monospace">${fmt(a.points[0].x)} s</text><text x="${w-right}" y="${h-10}" text-anchor="end" font-size="10" fill="#93a083" font-family="monospace">${fmt(a.points.at(-1).x)} s</text><text x="12" y="14" font-size="10" fill="#93a083" font-family="monospace">${e(a.unit)}</text></svg>`;}
function analysisDetails(t){const a=t.analysis;if(!a)return `<div class="card-pad notes">${e(t.notes||'No measurement CSV is attached to this record.')}</div>`;return `<div class="chart-wrap">${chart(a)}<div class="metrics">${[['Mean',`${fmt(a.mean)} ${a.unit}`],['Peak-to-peak',`${fmt(a.peakToPeak)} ${a.unit}`],['Min / max',`${fmt(a.min)} / ${fmt(a.max)}`],['Samples',a.count]].map(([label,v])=>`<div class="metric"><span>${label}</span><strong>${e(v)}</strong></div>`).join('')}</div><p class="notes">${a.status==='insufficient'?'No target and absolute tolerance were supplied. A pass cannot be determined.':`Checked all samples against ${fmt(a.target)} ± ${fmt(a.tolerance)} ${a.unit}; ${a.failed} of ${a.count} points are out of range.`}</p><p class="help">Peak-to-peak is the full-window maximum minus minimum, not necessarily steady-state ripple. Statistics do not replace electrical verification.</p>${t.notes?`<p class="notes">Lab notes: ${e(t.notes)}</p>`:''}</div>`;}
function tests(){return `<div class="page-head"><div><div class="eyebrow">EXPERIMENT NOTEBOOK</div><h1>Make every experiment count</h1><p class="subhead">Save test conditions, raw data and the exact design revision.</p></div><div class="tab-actions">${aiButton('test-plan','Plan tests')}${aiButton('analysis','Analyze results')}${button('compare-tests','Compare tests')}${button('import-test',icon('upload')+' Log / import test','primary')}</div></div>${savedDocuments(['test-plan','analysis'])}${p().tests.length?p().tests.map(t=>`<div class="card test-card"><div class="card-header"><div><h2>${e(t.title)} ${t.demo?badge('Sample data','warn'):''}</h2><div class="test-meta"><span>${e(t.version)}</span><span>${date(t.date)}</span><span>${e(t.filename||'Manual entry')}</span></div></div><div class="row">${status(t.analysis)}${aiButton('analysis','Analyze',t.id)}${button('view-test','Details','small',`data-id="${e(t.id)}"`)}</div></div><div style="padding:0 22px 8px" class="notes">Test conditions: ${e(t.conditions)}</div>${analysisDetails(t)}</div>`).join(''):`<div class="card">${empty('No tests yet','Import numeric CSV files from your instruments, or start with conditions and observations.','import-test','Log your first test')}</div>`}`;}
function timeline(){return `<div class="page-head"><div><div class="eyebrow">PROJECT MEMORY</div><h1>The story behind your design</h1><p class="subhead">What you tried, why you changed it, and the evidence behind each decision.</p></div><div class="row">${aiButton('summary','Summarize history')}${button('add-decision',icon('plus')+' Record decision','primary')}</div></div>${savedDocuments(['summary'])}<div class="card card-pad"><div class="timeline-full">${recentEvents(500)}</div></div>`;}
function assistant(){return `<div class="page-head"><div><div class="eyebrow">ENGINEERING COPILOT</div><h1>A thinking partner for your project</h1><p class="subhead">Requirements → Research → Test evidence → Next steps</p></div>${badge(connection.connected?`${connection.model} configured`:'AI not connected',connection.connected?'pass':'warn')}</div><div class="chat-layout"><div class="card chat-box"><div class="chat-messages" id="messages">${p().messages.length?p().messages.map((m,i)=>`<div class="message ${m.role==='user'?'user':''}"><div class="role">${m.role==='user'?'YOU':m.role==='system'?'SYSTEM':'CIRCUIT ASSISTANT'}</div><div class="text">${e(m.text)}</div>${m.sources?.length?`<div class="sources">${m.sources.map(s=>safeLink(s.url,s.title)).join('')}</div>`:''}${m.usage?`<div class="usage">INPUT ${m.usage.input_tokens??'—'} · CACHED ${m.usage.input_tokens_details?.cached_tokens??0} · OUTPUT ${m.usage.output_tokens??'—'} · ${e(m.model||'')} · ${((m.elapsed||0)/1000).toFixed(1)}s</div>`:''}${m.responseId?`<p class="help">Response ID: ${e(m.responseId)} · Returned model: ${e(m.returnedModel||'Not supplied')}</p>`:''}${m.role==='assistant'?`<div style="margin-top:12px">${button('save-message','Save as an unverified proposal','small',`data-index="${i}"`)}</div>`:''}</div>`).join(''):`<div class="empty"><div class="empty-icon">${icon('spark')}</div><h3>Advice grounded in your project</h3><p>The assistant reads requirements, blocks, the BOM and test statistics.<br>Raw CSV files are not sent automatically. AI does not modify your records.</p></div>`}${busy?'<div class="message"><div class="role">WORKING</div><p>Reviewing project context and preparing an answer…</p></div>':''}</div><form id="chat-form" class="chat-compose"><textarea name="message" aria-label="Ask the assistant" placeholder="Based on my test results, what should I measure next?" required maxlength="6000"></textarea><div class="row"><label class="inline"><input type="checkbox" name="research" ${!connection.search?'disabled':''}>Research manufacturer sources</label><button class="primary" type="submit" ${busy?'disabled':''}>${icon('arrow')} ${busy?'Thinking…':'Send'}</button></div><p class="status-note">${connection.connected?'Sending a message shares the project summary with the configured model provider.':'Configure the course key in .env to connect. No simulated AI answers are generated.'}${connection.connected&&!connection.search?' Web research is not enabled for this connection.':''}</p></form></div><div class="chat-aside stack"><div class="card card-pad"><h3>Project context</h3><div class="task-line">${icon('circuit')} ${p().stages.length} circuit blocks</div><div class="task-line">${icon('layers')} ${p().bom.length} components</div><div class="task-line">${icon('flask')} ${p().tests.length} test records</div><p class="help" style="margin-top:14px">${e(p().name)} / ${e(p().version)}<br>Only test summaries and conditions are sent. Suggestions still require engineering verification.</p></div><div class="card card-pad"><h3>Start with a useful question</h3><div class="prompts">${['Which design conditions are still missing from this project?','Review my system architecture and explain the key design tradeoffs.','Use my tests to suggest a measurement that distinguishes possible fault causes.'].map(q=>button('prompt',e(q),'',`data-prompt="${e(q)}"`)).join('')}</div></div></div></div>`;}
function settings(){const usages=p().messages.filter(m=>m.usage).map(m=>m.usage);const totals=usages.reduce((a,u)=>({input:a.input+(u.input_tokens||0),cached:a.cached+(u.input_tokens_details?.cached_tokens||0),output:a.output+(u.output_tokens||0)}),{input:0,cached:0,output:0});return `<div class="page-head"><div><div class="eyebrow">WORKSPACE SETTINGS</div><h1>Connections, data and usage</h1><p class="subhead">Projects live in this browser. Export backups regularly.</p></div></div><div class="grid-2"><div class="card"><div class="settings-section"><h2>AI connection</h2><p>${connection.connected?(connectionProof?'Server key configured · Live test succeeded':'Server key configured · Not a live verification'):'No server key configured'} · ${e(connection.provider)} · ${e(connection.model)}</p>${connection.connected?'':'<p>Configure your provider to enable AI assistance.</p>'}${connectionPanel()}<p>Keys stay on the server and are excluded from project exports. Local settings take effect immediately.</p>${connection.localConfiguration?button('configure-ai','Configure AI','small primary'):''}${button('verify-connection',connectionTesting?'Testing model…':'Run live connection test','small',connectionTesting?'disabled':'')}</div><div class="settings-section"><h2>Actual token usage</h2><div class="metrics"><div class="metric"><span>Input</span><strong>${totals.input}</strong></div><div class="metric"><span>Cached input</span><strong>${totals.cached}</strong></div><div class="metric"><span>Output</span><strong>${totals.output}</strong></div><div class="metric"><span>Logged calls</span><strong>${usages.length}</strong></div></div><p>Cached tokens are a subset of input. Costs are not estimated without configured prices. Provider billing is authoritative for failed calls.</p>${button('export-usage','Export usage JSON','small')}</div></div><div class="card"><div class="settings-section"><h2>Backups and handoff</h2><p>Data is stored in this browser without cross-device sync. Export project JSON to back up or transfer your work.</p><div class="tab-actions">${button('export-project',icon('down')+' Export project')}${button('import-project',icon('upload')+' Import project')}</div></div><div class="settings-section"><h2>Project handoff</h2><p>Export a standalone HTML handoff with requirements, blocks, the BOM, decisions, test charts and history. This is separate from the final course report.</p>${aiButton('handoff','Draft handoff')}${button('export-report','Export handoff','primary')}${savedDocuments(['handoff'])}</div><div class="settings-section"><h2>New project</h2><p>Create a blank hardware project. All requirements, components and measurements come from you.</p><div class="tab-actions">${button('new-project','Create project','small')}</div>${storageBroken?`<p class="error">The original archive is unreadable. Overwriting is disabled.</p>${button('raw-backup','Download original archive','small')}`:''}</div></div></div>`;}
function renderWelcome(){
 document.querySelector('#app').innerHTML=`<div class="welcome-shell"><header class="welcome-header"><div class="brand"><div class="brand-mark">${icon('circuit')}</div><div><strong>Circuit Journal</strong><small>HARDWARE, CONNECTED.</small></div></div><span class="badge">Your private engineering workspace</span></header><main class="welcome-main page-enter"><div class="eyebrow">IDEAS BECOME HARDWARE. EVIDENCE MAKES IT BETTER.</div><h1>Your next project<br>starts with a clean slate.</h1><p class="welcome-copy">Bring your idea, define your design, and keep every experiment connected. Your workspace starts empty, ready for your own projects and measurements.</p><div class="welcome-actions">${connection.localConfiguration?button('configure-ai',icon('settings')+' Configure AI'):''}${button('new-project',icon('plus')+' Create your first project','primary')}${button('import-project',icon('upload')+' Import a project backup')}</div><div class="welcome-grid">${[['circuit','Design with context','Keep requirements, circuit blocks, parts and decisions together.'],['flask','Learn from every test','Import your measurements, inspect results and compare revisions.'],['spark','Build on evidence','Research with AI and create a handoff others can understand.']].map(([i,t,d])=>`<section class="card card-pad"><div class="empty-icon">${icon(i)}</div><h2>${t}</h2><p>${d}</p></section>`).join('')}</div><div class="welcome-footer"><span>${icon('check')} No preloaded projects or measurement datasets</span><span>Stored in this browser · Export backups regularly</span></div>${storageBroken?`<div class="info-banner">Your existing archive could not be read. Export it before attempting recovery. ${button('raw-backup','Download original archive','small')}</div>`:''}</main></div>`;
 lastRenderedPage=null;
}

function render(){if(!p()){renderWelcome();return;}const nav=[['overview','grid','Overview'],['design','circuit','Design workbench'],['bom','layers','Bill of materials'],['tests','flask','Experiments'],['timeline','clock','Timeline'],['assistant','spark','AI assistant']];document.querySelector('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">${icon('circuit')}</div><div><strong>Circuit Journal</strong><small>HARDWARE, CONNECTED.</small></div></div><div class="nav-label">WORKSPACE</div><select class="project-select" id="project-select" aria-label="Switch project">${state.projects.map(x=>`<option value="${e(x.id)}" ${x.id===state.active?'selected':''}>${e(x.name)}</option>`).join('')}</select><nav class="nav">${nav.map(([id,ic,label])=>`<button class="${page===id?'active':''}" data-action="nav-${id}" title="${label}">${icon(ic)}<span>${label}</span>${id==='tests'?`<span class="count">${p().tests.length}</span>`:''}</button>`).join('')}<div style="height:14px"></div><button class="${page==='settings'?'active':''}" data-action="nav-settings" title="Settings & data">${icon('settings')}<span>Settings & data</span></button></nav><div class="sidebar-bottom"><div class="storage-note"><span class="dot"></span>Stored in this browser<br>Back up your work. Keep every experiment.</div><div class="person"><span class="avatar">CJ</span><div><strong style="font-size:11px;font-weight:500">Personal workspace</strong><br><small style="font-size:9px">Your next idea starts here.</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumbs">Workspace ${icon('chevron')} <strong>${nav.find(x=>x[0]===page)?.[2]||'Settings & data'}</strong></div><div class="top-actions"><span class="saved"><span class="dot"></span>${storageBroken?'Archive needs recovery':'Saved in this browser'}</span>${button('export-report',icon('down')+' Export handoff','small')}</div></header><div class="workspace">${({overview,design,bom,tests,timeline,assistant,settings}[page]||overview)()}${draftShelf()}</div></main></div>`;document.querySelector('#project-select').onchange=ev=>{mutate(()=>state.active=ev.target.value);render();};const form=document.querySelector('#chat-form');if(form)form.onsubmit=sendChat;if(lastRenderedPage!==page){document.querySelector('.workspace').classList.add('page-enter');lastRenderedPage=page;}document.querySelector('.nav button.active')?.setAttribute('aria-current','page');}
function openModal(title,body,submit,label='Save'){modalReturn=document.activeElement;document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${e(title)}"><div class="modal-head"><h2>${e(title)}</h2>${button('close-modal',icon('close'),'icon ghost','aria-label="Close"')}</div><form id="modal-form"><div class="modal-body">${body}<p class="error form-error" id="form-error"></p></div><div class="modal-foot">${button('close-modal','Cancel')}<button type="submit" class="primary">${label}</button></div></form></section></div>`;const f=document.querySelector('#modal-form');f.onsubmit=async ev=>{ev.preventDefault();const b=f.querySelector('button[type=submit]');b.disabled=true;b.classList.add('is-saving');b.setAttribute('aria-busy','true');try{await submit(Object.fromEntries(new FormData(f)),f);closeModal();render();}catch(err){document.querySelector('#form-error').textContent=err.message;b.disabled=false;b.classList.remove('is-saving');b.removeAttribute('aria-busy');}};setTimeout(()=>f.querySelector('input,textarea,select,button')?.focus(),0);}
function closeModal(){document.querySelector('#modal-form')?.abortRequest?.();const layer=document.querySelector('.modal-backdrop');if(!layer)return;layer.classList.add('closing');layer.inert=true;const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;setTimeout(()=>{layer.remove();modalReturn?.focus();},reduced?0:140);}
function projectModal(){openModal('Create hardware project',field('Project name','name','','For example: Wireless sensor node','text',true)+area('Project goal','description','','What are you building? What requirements must it meet?')+field('Category','category','','Power, sensors, embedded systems…'),v=>{const next=initialProject();Object.assign(next,{name:v.name,description:v.description,category:v.category||'Hardware R&D',stages:[],requirements:[],events:[{id:uid(),title:'Project created',detail:v.description,date:new Date().toISOString(),type:'project'}]});mutate(()=>{state.projects.push(next);state.active=next.id;});page='overview';toast('Project created');},'Create project');}
function stageModal(id){const s=p().stages.find(x=>x.id===id)||{name:'',kind:'MODULE',voltage:'',part:'',note:''};openModal(id?'Edit circuit block':'Add circuit block',field('Block name','name',s.name,'For example: Boost stage','text',true)+`<div class="field-grid">${select('Block type','kind',['INPUT','BOOST','BUCK','SWITCH','LDO','MCU','SENSOR','MODULE'].map(v=>[v,v]),s.kind)}${field('Output voltage (V, optional)','voltage',s.voltage,'Pending','number')}</div>`+field('Part number','part',s.part,'Leave blank if not selected')+area('Design notes / items to verify','note',s.note)+(id?button('delete-stage','Delete this block','small danger',`data-id="${e(id)}"`):''),v=>{mutate(()=>{const record={...v,id:id||uid()};if(id)p().stages[p().stages.findIndex(x=>x.id===id)]=record;else p().stages.push(record);event('Updated circuit block',`${v.name} · ${v.part||'Part number pending'}; ${v.note}`,'design');});toast('Block saved');});}
function draftRequirementsModal(){
 const project=p(),projectId=project.id;
 const old=project.requirementDraft;
 openModal('Describe your hardware idea',`<div class="info-banner">AI will extract stated goals and flag missing parameters. You review every item before it becomes a project requirement.</div>${area('Your idea and constraints','idea',old?.idea||project.description,'What should it do? Include any known inputs, outputs, load, size, cost and operating conditions.')}<p class="help">This sends your idea and the project design summary to the configured model provider. Raw measurements are not sent.</p>${old?'<p class="help">Generating again replaces the unsaved AI draft only. Existing requirements remain unchanged.</p>':''}`,()=>{},'Generate draft');
 const form=document.querySelector('#modal-form');
 form.onsubmit=async ev=>{
  ev.preventDefault();const idea=form.elements.idea.value.trim(),error=form.querySelector('#form-error'),submit=form.querySelector('button[type=submit]');
  if(!idea||idea.length>6000){error.textContent='Describe your idea using 1 to 6,000 characters.';return;}
  const controller=new AbortController();form.abortRequest=()=>controller.abort();
  submit.disabled=true;submit.classList.add('is-saving');submit.textContent='Drafting requirements…';submit.setAttribute('aria-busy','true');error.textContent='';
  const ctx={name:project.name,description:project.description,version:project.version,requirements:project.requirements,stages:project.stages,bom:project.bom};
  try{
   const response=await fetch('/api/requirements',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({message:idea,context:ctx}),signal:controller.signal});
   const result=await response.json();if(!response.ok)throw Error(result.error||'Unable to generate a draft.');
   if(!form.isConnected||controller.signal.aborted)return;
   mutate(()=>{const target=state.projects.find(x=>x.id===projectId);target.requirementDraft={id:uid(),idea,summary:result.draft.summary,questions:result.draft.questions,rows:result.draft.requirements.map(r=>({...r,id:uid(),include:true,status:'pending'})),created:new Date().toISOString(),model:result.model};target.messages.push({role:'assistant',text:'Requirements draft generated for review. '+result.draft.summary,model:result.model,usage:result.usage,elapsed:result.elapsed,date:new Date().toISOString()});target.events.unshift({id:uid(),title:'AI requirements draft prepared',detail:`${result.draft.requirements.length} proposed items; no requirements saved yet.`,date:new Date().toISOString(),type:'assistant'});});
   form.abortRequest=null;reviewRequirementsModal();render();
  }catch(err){if(controller.signal.aborted)return;if(form.isConnected){error.textContent=err.message;submit.disabled=false;submit.classList.remove('is-saving');submit.removeAttribute('aria-busy');submit.textContent='Generate draft';}}
 };
}
function reviewRequirementsModal(){
 const project=p(),draft=project.requirementDraft;if(!draft){toast('Generate a draft first.');return;}
 const draftId=draft.id;
 const body=`<div class="info-banner">${e(draft.summary)}<br>Review the values, deselect unwanted items, and explicitly choose Confirmed where appropriate. All items start as Pending.</div>${draft.questions.length?`<div class="clarification-panel"><h3>Questions to resolve</h3><ol>${draft.questions.map(q=>`<li>${e(q)}</li>`).join('')}</ol><p class="help">Fill answers into the relevant values below, or close this review and generate again with more detail.</p></div>`:''}<div class="requirement-draft-list">${draft.rows.map((r,i)=>`<section class="requirement-draft-row" data-draft-row="${i}"><div class="row"><label class="inline"><input type="checkbox" name="include_${i}" ${r.include?'checked':''}>Include requirement ${i+1}</label>${badge(r.basis==='stated'?'From your description':r.basis==='missing'?'Missing information':'Proposed for review',r.basis==='stated'?'':'warn')}</div>${field('Requirement name','name_'+i,r.name)}${field('Value / acceptance condition','value_'+i,r.value)}${select('Review status','status_'+i,[['pending','Pending'],['confirmed','Confirmed']],r.status)}<p class="help">${e(r.rationale)}</p>${r.source_quote?`<details><summary>Source evidence</summary><p class="notes">${e(r.source_quote)}</p></details>`:''}</section>`).join('')}</div><p class="help">Only selected items are added. Existing requirements are never overwritten. Unknown values must stay Pending.</p>`;
 openModal('Review AI requirements',body,(values,form)=>{
  if(p().id!==project.id||project.requirementDraft?.id!==draftId)throw Error('The project or draft changed. Reopen the latest draft.');
  const selected=draft.rows.map((row,i)=>({...row,include:form.elements['include_'+i].checked,name:form.elements['name_'+i].value.trim(),value:form.elements['value_'+i].value.trim(),status:form.elements['status_'+i].value})).filter(r=>r.include);
  if(!selected.length)throw Error('Select at least one requirement to save.');
  const names=new Set(project.requirements.map(r=>r.name.trim().toLowerCase()));
  for(const r of selected){if(!r.name||!r.value)throw Error('Every selected item needs a name and value.');if(r.name.length>120||r.value.length>500)throw Error('Keep names under 120 characters and values under 500.');if(names.has(r.name.toLowerCase()))throw Error(`A requirement named "${r.name}" already exists. Rename it or deselect it.`);names.add(r.name.toLowerCase());if(r.status==='confirmed'&&/^(tbd|unknown|pending|to be (determined|confirmed|defined)|not specified|n\/a)$/i.test(r.value))throw Error(`"${r.name}" still has an unknown value. Keep it Pending.`);}
  mutate(()=>{project.requirements.push(...selected.map(({name,value,status,basis,rationale,source_quote})=>({id:uid(),name,value,status,origin:'ai-reviewed',basis,rationale,source_quote,reviewedAt:new Date().toISOString()})));project.requirementDraft=null;event('Saved reviewed AI requirements',`${selected.length} items added; ${selected.filter(r=>r.status==='confirmed').length} explicitly confirmed.`,'design');});
  page='design';toast(`${selected.length} requirements saved`);
 },'Save selected requirements');
 const form=document.querySelector('#modal-form');
 form.addEventListener('input',()=>{try{mutate(()=>{draft.rows.forEach((row,i)=>{row.include=form.elements['include_'+i].checked;row.name=form.elements['name_'+i].value;row.value=form.elements['value_'+i].value;row.status=form.elements['status_'+i].value;});});}catch(err){form.querySelector('#form-error').textContent=err.message;}});
}
function requirementModal(id){const r=p().requirements.find(x=>x.id===id)||{name:'',value:'',status:'pending'};openModal('Requirements',field('Requirement name','name',r.name,'For example: Full-load output current','text',true)+field('Value / conditions','value',r.value,'For example: 1 A at 25°C ambient','text',true)+select('Confirmation status','status',[['pending','Pending'],['confirmed','Confirmed']],r.status),v=>mutate(()=>{if(id)Object.assign(r,v);else p().requirements.push({...v,id:uid()});event('Updated requirement',`${v.name}: ${v.value}`,'design');}));}
function partModal(id){const r=p().bom.find(x=>x.id===id)||{ref:'',part:'',value:'',qty:'1',source:''};openModal(id?'Edit part':'Add part',`<div class="field-grid">${field('Reference','ref',r.ref,'U1 / L1 / C1','text',true)}${field('Quantity','qty',r.qty,'1','number',true)}</div>`+field('Exact part number','part',r.part,'Enter TBD if not yet selected','text',true)+field('Purpose / parameters','value',r.value,'For example: Boost controller')+field('Manufacturer documentation URL','source',r.source,'https://...','url')+(id?button('delete-part','Delete this part','small danger',`data-id="${e(id)}"`):''),v=>{if(!Number.isInteger(Number(v.qty))||Number(v.qty)<1)throw Error('Quantity must be a positive integer.');if(v.source&&!/^https?:\/\//i.test(v.source))throw Error('Source links must begin with https:// or http://.');mutate(()=>{if(id)Object.assign(r,v);else p().bom.push({...v,id:uid()});event('Updated component',`${v.ref} · ${v.part} × ${v.qty}`,'design');});toast('Part saved');});}
function decisionModal(title='',detail=''){openModal('Record design decision',field('Decision title','title',title,'What did you decide?','text',true)+area('Evidence, tradeoffs and open questions','detail',detail,'Why this choice? What evidence supports it? How will you verify it?'),v=>mutate(()=>{p().decisions.unshift({...v,id:uid(),date:new Date().toISOString()});event('Record design decision',v.title,'decision');}));}
function testModal(){let parsed=null,raw='',filename='';openModal('Log an experiment',field('Test name','title','','For example: 10V steady-state output test','text',true)+`<div class="field-grid">${field('Design revision','version',p().version,'V1','text',true)}${field('Test date and time','date',new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16),'','datetime-local',true)}</div>`+area('Test conditions (required)','conditions','','Instrument, test point, input, load, bandwidth, probe, firmware and board changes…')+`<label class="field">Measurement CSV (optional; 2 MB / 10,000 rows max)<input type="file" id="csv-file" accept=".csv,text/csv"></label><p class="help">Use column headers and a time column in seconds. Convert other time units before importing. Data stays in this browser.</p><div id="csv-mapping"></div>`+area('Observations and notes','notes','','What did you observe? What did you try?'),v=>{if(!v.conditions.trim())throw Error('Record the test conditions so the experiment can be reproduced.');if(!parsed&&!v.notes.trim())throw Error('Import a CSV or enter your observations.');let analysis=null,mapping=null;if(parsed){mapping={x:v.x,y:v.y,unit:v.unit,target:v.target,tolerance:v.tolerance};analysis=analyzeCSV(parsed,mapping);}const record={id:uid(),title:v.title,version:v.version,date:new Date(v.date).toISOString(),conditions:v.conditions,notes:v.notes,filename,rawCSV:raw,mapping,analysis,designSnapshot:JSON.parse(JSON.stringify({version:p().version,stages:p().stages,bom:p().bom,requirements:p().requirements})),demo:Boolean(p().demo)};if(v.version!==p().version){const rev=p().revisions.find(r=>r.version===v.version);if(!rev)throw Error('No snapshot exists for that revision. Use the current revision or save a matching snapshot first.');record.designSnapshot=rev.snapshot;}mutate(()=>{p().tests.unshift(record);event('Log test',`${v.title} · ${v.version} · ${analysis?analysis.count+' samples':'Manual notes'}`,'test');});page='tests';toast('Test and design snapshot saved');},'Save test');document.querySelector('#csv-file').onchange=async ev=>{parsed=null;raw='';filename='';const mapping=document.querySelector('#csv-mapping'),err=document.querySelector('#form-error');err.textContent='';mapping.innerHTML='';const file=ev.target.files[0];if(!file)return;try{if(file.size>2_000_000)throw Error('File exceeds 2 MB. Export a smaller segment.');const text=await file.text();parsed=parseCSV(text);raw=text;filename=file.name;mapping.innerHTML=`<div class="file-preview">✓ ${e(file.name)} · ${parsed.rows.length} rows · ${parsed.headers.length} columns</div><div class="field-grid">${select('Time column (seconds)','x',parsed.headers.map(h=>[h,h]),parsed.headers[0])}${select('Measurement column','y',parsed.headers.map(h=>[h,h]),parsed.headers[1])}</div><div class="field-grid">${select('CSV measurement unit','unit',[['V','V'],['mV','mV'],['A','A'],['mA','mA'],['C','°C']],'V')}${field('Target (converted V / A / °C)','target','','Optional','number')}</div>${field('Absolute tolerance (converted V / A / °C)','tolerance','','For example: 0.1, not a percentage','number')}<p class="help">Leave limits blank for statistics only. Range checks cover the full sample window.</p>`;}catch(error){err.textContent=error.message;ev.target.value='';}};}
function showTest(id){const t=p().tests.find(x=>x.id===id);openModal(t.title,`<div class="row">${badge(t.version)}${status(t.analysis)}</div><p class="notes" style="margin-top:16px">Test conditions: ${e(t.conditions)}</p>${analysisDetails(t)}<h3>Design snapshot at test time</h3><p class="help">${e((t.designSnapshot?.stages||[]).map(s=>`${s.name} (${s.part||'TBD'})`).join(' → '))}</p>${t.rawCSV?button('download-raw','Download raw CSV','small',`data-id="${e(t.id)}"`):''}<div style="margin-top:20px">${button('delete-test','Delete this test','small danger',`data-id="${e(t.id)}"`)}</div>`,()=>{},'Close');}
function compareTests(){const options=p().tests.filter(t=>t.analysis).map(t=>[t.id,`${t.title} · ${t.version}${t.demo?' [Sample]':''}`]);if(options.length<2){toast('At least two tests with CSV data are required.');return;}openModal('Compare two tests',select('Baseline test','before',options,options[0][0])+select('Comparison test','after',options,options[1][0])+'<p class="help">Compare load, test points, sampling and instrument settings first. A numerical change does not necessarily mean improvement.</p><div id="comparison"></div>',()=>{},'Close');const update=()=>{const f=document.querySelector('#modal-form'),a=p().tests.find(t=>t.id===f.elements.before.value),b=p().tests.find(t=>t.id===f.elements.after.value),el=document.querySelector('#comparison');if(a.id===b.id){el.innerHTML='<p class="error">Choose two different tests.</p>';return;}if(a.analysis.unit!==b.analysis.unit){el.innerHTML='<p class="error">Different measurement units cannot be compared directly.</p>';return;}el.innerHTML=`<div class="info-banner">Baseline conditions: ${e(a.conditions)}<br>Comparison conditions: ${e(b.conditions)}</div><table><thead><tr><th>Metric (${e(a.analysis.unit)})</th><th>Baseline</th><th>Comparison</th><th>Change</th></tr></thead><tbody>${[['mean','Mean'],['peakToPeak','Peak-to-peak'],['std','Standard deviation']].map(([k,l])=>`<tr><td>${l}</td><td>${fmt(a.analysis[k])}</td><td>${fmt(b.analysis[k])}</td><td>${fmt(b.analysis[k]-a.analysis[k])}</td></tr>`).join('')}</tbody></table>`;};document.querySelectorAll('#modal-form select').forEach(s=>s.onchange=update);update();}
function context(){const project=p();return {name:project.name,description:project.description,version:project.version,requirements:project.requirements,stages:project.stages,bom:project.bom,events:project.events.slice(0,20),decisions:project.decisions.slice(0,5),tests:project.tests.slice(0,5).map(({title,version,conditions,notes,analysis,demo})=>({title,version,conditions,notes,demo,statistics:analysis?Object.fromEntries(Object.entries(analysis).filter(([k])=>k!=='points')):null})),recentConversation:project.messages.slice(-4).map(({role,text})=>({role,text:text.slice(0,3000)}))};}
async function sendChat(ev){ev.preventDefault();if(busy)return;const f=ev.target,message=f.elements.message.value.trim(),research=f.elements.research.checked;if(!message)return;const projectId=p().id;const ctx=context();try{mutate(()=>p().messages.push({role:'user',text:message,date:new Date().toISOString()}));}catch(err){toast(err.message);return;}busy=true;render();try{const res=await fetch('/api/assistant',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({message,research,context:ctx})});const data=await res.json();if(!res.ok)throw Error(data.error||'Request failed.');mutate(()=>{const target=state.projects.find(x=>x.id===projectId);target.messages.push({role:'assistant',...data,date:new Date().toISOString()});target.events.unshift({id:uid(),title:'AI project analysis',detail:`${data.model} · Suggestions require engineering verification${data.incomplete?' · Output truncated at the configured limit':''}`,date:new Date().toISOString(),type:'assistant'});});}catch(err){toast(err.message);const target=state.projects.find(x=>x.id===projectId);try{mutate(()=>target.messages.push({role:'system',text:'Request incomplete: '+err.message,date:new Date().toISOString()}));}catch{}}finally{busy=false;render();document.querySelector('#messages')?.scrollTo(0,999999);}}
async function refreshStatus(){try{const res=await fetch('/api/status');connection=await res.json();}catch{connection={connected:false,model:'gpt-6-luna',provider:'Portkey'};}render();}

const moduleLabels={architecture:'Architecture blocks',bom:'Bill of materials','test-plan':'Test plan',analysis:'Result analysis',decision:'Design decision',handoff:'Project handoff',summary:'Project history'};
const moduleFields={architecture:['name','kind','voltage','part','note'],bom:['ref','part','value','qty','source'],'test-plan':['title','detail'],analysis:['title','detail'],decision:['title','detail'],handoff:['title','detail'],summary:['title','detail']};
function aiButton(module,label,id=''){return button('ai-module',icon('spark')+' '+label,'small',`data-module="${module}" data-id="${e(id)}"`);}
function savedDocuments(kinds){const docs=p().decisions.filter(d=>kinds.includes(d.module));return docs.map(d=>`<div class="card card-pad section-gap"><h3>${e(d.title)} ${badge(d.module==='test-plan'?'Not executed':'AI interpretation · Reviewed','warn')}</h3><p class="notes">${e(d.detail)}</p><small>${e(d.model||'')} · ${date(d.date)}</small></div>`).join('');}
function draftShelf(){const pending=p().messages.map((m,i)=>({m,i})).filter(({m})=>m.moduleDraft&&!m.applied);return pending.length?`<div class="card card-pad section-gap"><h3>AI drafts awaiting your review</h3>${pending.map(({m,i})=>`<div class="row"><span>${e(moduleLabels[m.module])} · ${date(m.date)}</span>${button('review-module','Review draft','small',`data-index="${i}"`)}</div>`).join('')}</div>`:'';}
async function configureAI(){
 const response=await fetch('/api/configuration');const config=await response.json();if(!response.ok)throw Error(config.error||'Configuration is available only on the local server.');
 openModal('Configure AI',`<p class="help">Choose your own provider. Saved credentials are stored in .local-ai.json on this computer, with owner-only file permissions. They are not encrypted and are never included in project exports or browser storage.</p>${select('Provider','provider',[['Portkey','Course Portkey'],['OpenAI','OpenAI']],config.provider)}${field('API key','key','','Leave blank to keep the current provider key','password')}${field('Model','model',config.model,'Enter a model available to your account','text',true)}<p class="help" id="provider-help"></p><p class="help">Current configuration: ${e(config.source)} · ${config.configured?'Key configured':'No key configured'}. Saving a key does not verify access.</p><div class="row">${button('test-config','Test saved connection','small')}${button('disconnect-config','Disconnect AI','small danger')}</div><div id="config-proof">${connectionPanel()}</div>`,async(v)=>{
  if(connectionTesting)throw Error('Wait for the connection test to finish before changing settings.');
  const res=await fetch('/api/configuration',{method:'POST',headers:{'content-type':'application/json','x-configuration-token':config.token},body:JSON.stringify(v)});const result=await res.json();if(!res.ok)throw Error(result.error||'Could not save configuration.');connectionProof=null;connectionError='';await refreshStatus();toast('AI configuration saved. No restart needed.');
 },'Save configuration');
 const form=document.querySelector('#modal-form');form.elements.key.autocomplete='off';form.elements.key.spellcheck=false;
 const updateProvider=()=>{const course=form.elements.provider.value==='Portkey';form.elements.model.readOnly=course;if(course)form.elements.model.value='gpt-6-luna';else if(form.elements.model.value==='gpt-6-luna')form.elements.model.value=config.provider==='OpenAI'?config.model:'';form.querySelector('#provider-help').textContent=course?'Course Portkey uses gpt-6-luna.':'Enter the exact model identifier enabled for your OpenAI API account.';};form.elements.provider.onchange=()=>{form.elements.key.value='';updateProvider();};updateProvider();
 form.querySelector('[data-action="test-config"]').onclick=async()=>{const b=form.querySelector('[data-action="test-config"]');b.disabled=true;form.querySelector('#config-proof').textContent='Testing the saved configuration. Save any edited fields first…';await verifyConnection();if(form.isConnected){form.querySelector('#config-proof').innerHTML=connectionPanel();b.disabled=false;}};
 form.querySelector('[data-action="disconnect-config"]').onclick=async()=>{try{if(connectionTesting)throw Error('Wait for the connection test to finish before disconnecting.');const res=await fetch('/api/configuration',{method:'POST',headers:{'content-type':'application/json','x-configuration-token':config.token},body:JSON.stringify({action:'disconnect'})});const result=await res.json();if(!res.ok)throw Error(result.error);connectionProof=null;connectionError='';await refreshStatus();closeModal();toast('AI disconnected. Saved local key removed; environment files unchanged.');}catch(err){form.querySelector('#form-error').textContent=err.message;}};
}

function connectionPanel(){if(connectionTesting)return '<p role="status">Sending a real request to the model provider…</p>';if(connectionError)return `<p class="error">Live test failed: ${e(connectionError)}</p>`;if(!connectionProof)return '<p class="help">Not tested in this session. A configured key does not prove model access.</p>';const r=connectionProof;return `<div class="info-banner"><strong>Live response received</strong><p>${e(r.text)}</p><p>Provider: ${e(r.provider)}<br>Requested model: ${e(r.model)}<br>Returned model: ${e(r.returnedModel||'Not supplied by provider')}<br>Response ID: ${e(r.responseId||'Not supplied by provider')}<br>Time: ${e(r.verifiedAt)}<br>Latency: ${(r.elapsed/1000).toFixed(2)} s<br>Tokens: ${r.usage?.input_tokens??'Unavailable'} input / ${r.usage?.output_tokens??'Unavailable'} output</p></div>`;}
async function verifyConnection(){if(connectionTesting)return;const target=p();connectionTesting=true;connectionProof=null;connectionError='';render();try{const res=await fetch('/api/connection-test',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({message:'Connection test. Confirm receipt.',context:{}})});const data=await res.json();if(!res.ok)throw Error(data.error||'Connection test failed.');if(data.incomplete)throw Error('The model response was incomplete. Retry the test.');connectionProof=data;if(target)mutate(()=>target.messages.push({...data,role:'assistant',text:'Connection test: '+data.text,date:new Date().toISOString()}));}catch(err){connectionProof=null;connectionError=err.message;}finally{connectionTesting=false;render();}}
function draftModuleModal(module,testId=''){
 if(!moduleFields[module])return;
 const project=p(),projectId=project.id,ctx=context();
 if(module==='analysis'&&!project.tests.length){toast('Import measurements or record observations before requesting analysis.');return;}
 if(testId){const test=project.tests.find(t=>t.id===testId);if(!test)return;ctx.tests=[{id:test.id,title:test.title,version:test.version,conditions:test.conditions,notes:test.notes,statistics:test.analysis?Object.fromEntries(Object.entries(test.analysis).filter(([k])=>k!=='points')):null,designSnapshot:test.designSnapshot}];}
 openModal('AI · '+moduleLabels[module],`<div class="info-banner">Create an editable proposal from your project evidence. You choose what to save. ${module==='architecture'?'This produces system blocks, not a pin-level schematic.':''}${module==='test-plan'?'Plans are not executed experiments.':''}</div>${area('What should AI help with?','idea','', 'Describe the goal, constraints, changes or questions you want addressed.')}<label class="inline"><input type="checkbox" name="research" ${module==='bom'?'checked':''}>Research manufacturer documentation</label><p class="help">Sends your request, design context, recent project history and test summaries to the model provider. Raw CSV data is not sent. Missing values remain unspecified.</p>`,()=>{},'Generate draft');
 const form=document.querySelector('#modal-form');form.onsubmit=async ev=>{
  ev.preventDefault();const error=form.querySelector('#form-error'),submit=form.querySelector('button[type=submit]'),idea=form.elements.idea.value.trim()||`Draft ${moduleLabels[module]} based on the recorded project. Identify missing information.`;
  if(idea.length>6000){error.textContent='Use at most 6,000 characters.';return;}
  const controller=new AbortController();form.abortRequest=()=>controller.abort();submit.disabled=true;submit.classList.add('is-saving');submit.textContent='Reading evidence and drafting…';error.textContent='';
  try{const res=await fetch('/api/draft',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({message:idea,module,context:ctx,research:form.elements.research.checked}),signal:controller.signal});const data=await res.json();if(!res.ok)throw Error(data.error||'Draft failed.');if(p()?.id!==projectId)throw Error('The active project changed. Please regenerate in the correct project.');let index;mutate(()=>{index=project.messages.length;project.messages.push({...data,role:'assistant',module,moduleDraft:data.draft,testId,applied:false,date:new Date().toISOString()});event('AI draft prepared',moduleLabels[module]+' · Awaiting review','assistant');});form.abortRequest=null;reviewModuleDraft(index);render();
  }catch(err){if(err.name==='AbortError')return;error.textContent=err.message;submit.disabled=false;submit.classList.remove('is-saving');submit.textContent='Generate draft';}
 };
}
function reviewModuleDraft(index){
 const project=p(),message=project.messages[index];if(!message?.moduleDraft||message.applied)return;
 const module=message.module,fields=moduleFields[module],draft=message.moduleDraft;if(!fields||!Array.isArray(draft.items))throw Error('Invalid stored draft.');
 openModal('Review · '+moduleLabels[module],`<p class="notes">${e(draft.summary)}</p><p class="help">AI proposals are unverified. Edit fields and select items to append. Existing records are preserved.</p>${message.sources?.map(s=>safeLink(s.url,s.title)).join(' ')||''}${draft.items.map((r,i)=>`<section class="card card-pad section-gap"><label class="inline"><input type="checkbox" name="include_${i}" checked>Save this item</label>${fields.map(k=>['detail','note','value'].includes(k)?area(k,`${k}_${i}`,r[k]):k==='kind'?select('kind',`${k}_${i}`,['INPUT','BOOST','BUCK','SWITCH','LDO','MCU','SENSOR','MODULE'].map(x=>[x,x]),r[k]):field(k,`${k}_${i}`,r[k])).join('')}</section>`).join('')}<p class="help">Model: ${e(message.model)} · Response: ${e(message.responseId||'Not supplied')}</p>`,(v,form)=>{
  if(p()!==project||message.applied)throw Error('The project changed. Reopen the draft.');
  const items=draft.items.map((r,i)=>({include:form.elements['include_'+i].checked,...Object.fromEntries(fields.map(k=>[k,form.elements[k+'_'+i].value.trim()]))})).filter(r=>r.include);
  if(!items.length)throw Error('Select at least one item.');
  const existing=new Set((module==='architecture'?project.stages:module==='bom'?project.bom:[]).map(r=>(r.name||r.ref).toLowerCase()));
  for(const r of items){if(!(r.name||r.ref||r.title))throw Error('Each selected item needs a name.');if(fields.some(k=>r[k].length>8000))throw Error('A field exceeds 8,000 characters.');if(module==='architecture'&&r.voltage!==''&&!Number.isFinite(Number(r.voltage)))throw Error('Voltage must be numeric or empty.');if(module==='bom'&&(!/^\d+$/.test(r.qty)||Number(r.qty)<1||Number(r.qty)>100000||!r.part||(r.source&&!/^https?:\/\//i.test(r.source))))throw Error('Enter a positive quantity, part number or TBD, and a valid source URL.');if('detail'in r&&!r.detail)throw Error('Enter the document content.');if(module==='architecture'||module==='bom'){const key=(r.name||r.ref).toLowerCase();if(existing.has(key))throw Error('Duplicate name or reference: '+key+'. Rename or deselect it.');existing.add(key);}}
  mutate(()=>{for(const {include,...r} of items){const record={...r,id:uid(),origin:'ai-reviewed',module,model:message.model,responseId:message.responseId,testId:message.testId,date:new Date().toISOString()};if(module==='architecture')project.stages.push(record);else if(module==='bom')project.bom.push(record);else project.decisions.unshift(record);}message.applied=true;event('Saved reviewed AI draft',moduleLabels[module]+' · '+items.length+' items','design');});toast('Reviewed draft saved');
 },'Save selected items');
}

function exportReport(){const project=p();const html=`<!doctype html><html lang="en"><head><meta charset="utf-8"><title>${e(project.name)} · Project handoff</title><style>body{font:14px system-ui,sans-serif;color:#233d31;max-width:1000px;margin:50px auto;padding:0 30px;line-height:1.8}h1{font-size:30px}h2{margin-top:35px;border-bottom:1px solid #dce5d4;padding-bottom:9px}table{border-collapse:collapse;width:100%;font-size:12px}td,th{padding:9px;text-align:left;border-bottom:1px solid #e5eade}svg{width:100%;height:auto}.metrics{display:flex;gap:20px}.metric{padding:10px;background:#f4f7ee}.metric span{display:block;color:#849176;font-size:11px}.help,small{color:#809071}.notes{white-space:pre-wrap}.badge{font-size:11px;color:#587a3c}.event{margin-bottom:15px}a{color:#24644b}@media print{body{margin:15mm;max-width:none}h2{break-after:avoid}table,.chart{break-inside:avoid}}</style></head><body><p>CIRCUIT JOURNAL / PROJECT HANDOFF</p><h1>${e(project.name)}</h1><p>${e(project.description)}</p><p>Revision ${e(project.version)} · Exported at ${e(new Date().toLocaleString('en-US'))}</p><p>This document records the current project state. System diagrams are architecture drafts.${project.demo?'This project uses synthetic sample data.':''}</p><h2>1. Requirements and constraints</h2><table>${project.requirements.map(r=>`<tr><td>${e(r.name)}</td><td>${e(r.value)}</td><td>${r.status==='confirmed'?'Confirmed':'Pending'}</td></tr>`).join('')}</table><h2>2. System architecture</h2>${schematicSVG(project)}<table>${project.stages.map(s=>`<tr><td>${e(s.name)}</td><td>${e(s.part)}</td><td>${e(s.note)}</td></tr>`).join('')}</table><h2>3. Bill of materials</h2><table><tr><th>Reference</th><th>Part number</th><th>Purpose</th><th>Quantity</th><th>Source</th></tr>${project.bom.map(r=>`<tr><td>${e(r.ref)}</td><td>${e(r.part)}</td><td>${e(r.value)}</td><td>${e(r.qty)}</td><td>${safeLink(r.source)}</td></tr>`).join('')}</table><h2>4. Design decisions</h2>${project.decisions.map(d=>`<h3>${e(d.title)}</h3><p class="notes">${e(d.detail)}</p>`).join('')||'<p>Nothing recorded yet.</p>'}<h2>5. Tests and evidence</h2>${project.tests.map(t=>`<h3>${e(t.title)} ${t.demo?'[Synthetic sample]':''}</h3><p>Revision ${e(t.version)} · ${date(t.date)}</p><p class="notes">Conditions: ${e(t.conditions)}</p>${status(t.analysis)}${analysisDetails(t)}`).join('')||'<p>No actual measurements have been imported. Pass status or improvement cannot be inferred.</p>'}<h2>6. Timeline</h2>${recentEvents(500)}<h2>7. Handoff notes</h2><p>AI suggestions are not verified facts. Continue validation with raw CSV files, design files, datasheets and hardware inspection. Export project JSON for complete raw data and design snapshots.</p></body></html>`;download('project-handoff.html',html,'text/html');toast('Standalone HTML handoff exported');}
async function action(name,el){if(name.startsWith('nav-')){page=name.slice(4);render();window.scrollTo(0,0);return;}switch(name){case 'close-modal':closeModal();return;case 'new-project':projectModal();return;case 'add-stage':stageModal();return;case 'edit-stage':stageModal(el.dataset.id);return;case 'draft-requirements':draftRequirementsModal();return;case 'review-requirements':reviewRequirementsModal();return;case 'add-requirement':requirementModal();return;case 'edit-requirement':requirementModal(el.dataset.id);return;case 'add-part':partModal();return;case 'edit-part':partModal(el.dataset.id);return;case 'add-decision':decisionModal();return;case 'import-test':testModal();return;case 'view-test':showTest(el.dataset.id);return;case 'compare-tests':compareTests();return;case 'export-svg':download('system-architecture.svg',schematicSVG(p()),'image/svg+xml');break;case 'export-bom':{const csv=[['Reference','Part','Description','Quantity','Source'],...p().bom.map(r=>[r.ref,r.part,r.value,r.qty,r.source])].map(row=>row.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');download('bom.csv','\uFEFF'+csv,'text/csv');break;}case 'export-project':download('circuit-project.json',JSON.stringify(p(),null,2),'application/json');break;case 'export-report':exportReport();break;case 'export-usage':download('agent-runs.json',JSON.stringify(p().messages.filter(m=>m.usage),null,2),'application/json');break;case 'raw-backup':download('raw-storage-backup.json',localStorage.getItem(KEY)||'','application/json');break;case 'import-project':{openModal('Import project backup','<label class="field">Circuit Journal project JSON<input type="file" name="file" accept=".json,application/json" required></label><p class="help">Import as a new copy, keeping existing projects.</p>',async(v,f)=>{const file=f.elements.file.files[0];if(file.size>4_000_000)throw Error('Project file exceeds 4 MB.');const next=validateProject(JSON.parse(await file.text()));next.id=uid();mutate(()=>{state.projects.push(next);state.active=next.id;});page='overview';toast('Imported as a new project copy');},'Import');return;}case 'new-revision':openModal('Save revision snapshot',field('Current revision name','version',p().version,'V1','text',true)+area('Revision notes','note','','What changed, and why?')+field('Next working revision (optional)','next','','For example: V2'),v=>{if(p().revisions.some(r=>r.version===v.version))throw Error('A snapshot already exists for this revision. Use a new revision name.');mutate(()=>{p().revisions.unshift({id:uid(),version:v.version,date:new Date().toISOString(),note:v.note,snapshot:JSON.parse(JSON.stringify({version:v.version,stages:p().stages,bom:p().bom,requirements:p().requirements}))});p().version=v.next.trim()||v.version;event('Saved design snapshot',`${v.version}: ${v.note}`,'version');});});return;case 'view-revision':{const r=p().revisions.find(x=>x.id===el.dataset.id);openModal('Design snapshot · '+r.version,`<p class="notes">${e(r.note||'')}</p><pre class="raw-preview">${e(JSON.stringify(r.snapshot,null,2))}</pre>`,()=>{},'Close');return;}case 'configure-ai':await configureAI();return;case 'verify-connection':await verifyConnection();return;case 'ai-module':draftModuleModal(el.dataset.module,el.dataset.id);return;case 'review-module':reviewModuleDraft(Number(el.dataset.index));return;case 'prompt':document.querySelector('#chat-form textarea').value=el.dataset.prompt;document.querySelector('#chat-form textarea').focus();return;case 'save-message':{const m=p().messages[Number(el.dataset.index)];decisionModal('AI proposal · Unverified',m.text);return;}case 'download-raw':{const t=p().tests.find(t=>t.id===el.dataset.id);download(t.filename||'measurements.csv',t.rawCSV,'text/csv');return;}case 'delete-stage':case 'delete-part':case 'delete-test':{const key={'delete-stage':'stages','delete-part':'bom','delete-test':'tests'}[name],id=el.dataset.id;openModal('Confirm deletion','<p class="notes">This deletes the selected record. Existing snapshots remain unchanged. Export a backup first if needed.</p>',()=>mutate(()=>{const item=p()[key].find(x=>x.id===id);p()[key]=p()[key].filter(x=>x.id!==id);event('Deleted record',item?.title||item?.name||item?.part||id,'delete');}),'Delete');return;}default:return;}render();}
document.addEventListener('click',ev=>{const el=ev.target.closest('[data-action]');if(el)Promise.resolve(action(el.dataset.action,el)).catch(err=>toast(err.message));});
document.addEventListener('keydown',ev=>{const modal=document.querySelector('.modal');if(!modal)return;if(ev.key==='Escape'){closeModal();return;}if(ev.key==='Tab'){const items=[...modal.querySelectorAll('button,input,textarea,select,a[href]')].filter(x=>!x.disabled);if(!items.length)return;const first=items[0],last=items.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus();}}});
document.addEventListener('pointerdown',ev=>{
 const control=ev.target.closest('button');
 if(!control||control.disabled||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const rect=control.getBoundingClientRect(),size=Math.max(rect.width,rect.height)*2;
 const wave=document.createElement('span');wave.className='press-wave';wave.setAttribute('aria-hidden','true');
 Object.assign(wave.style,{width:size+'px',height:size+'px',left:(ev.clientX-rect.left-size/2)+'px',top:(ev.clientY-rect.top-size/2)+'px'});
 control.append(wave);wave.addEventListener('animationend',()=>wave.remove(),{once:true});
});
render();refreshStatus();
